            var t = (ListMetricsResponse)GCHandle.FromIntPtr(run->Target).Target;
            byte* b = run->Buf;
            var e = t.Batches[(int)token];
            var lst = e.Values;
            for (int k = 0; k < n; k++) lst.Add(xs[k]);
        }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_batches_codes(IntPtr ctx, void* obj, long token, int* xs, int n)
    {
        _rev++;
        try
        {
            var run = (DecRun*)obj;
            var t = (ListMetricsResponse)GCHandle.FromIntPtr(run->Target).Target;
            byte* b = run->Buf;
            var e = t.Batches[(int)token];
            var lst = e.Codes;
            for (int k = 0; k < n; k++) lst.Add(xs[k]);
        }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_batches_flags(IntPtr ctx, void* obj, long token, byte* xs, int n)
    {
