    public ListMetricsResponse Decode(byte[] src, int len)
    {
        if (_dctx == IntPtr.Zero)
        {
            _dctx = Abi.ak_dec_ctx_new();
            _drun = (DecRun*)NativeMemory.Alloc((nuint)sizeof(DecRun));
        }
        Abi.ak_dec_err_reset(_dctx);
        var target = new ListMetricsResponse();
        var h = GCHandle.Alloc(target);
        try
        {
            fixed (byte* b = src)
            {
                _drun->Target = GCHandle.ToIntPtr(h);
                _drun->Buf = b;
                var vt = new ak_dvt_ListMetricsResponse
                {
                    apply = &ApplyRoot,
                    unknown = IntPtr.Zero,
                    unk_batches = IntPtr.Zero,
                    new_batches = &New_batches,
                    apply_batches = &Apply_batches,
                    add_batches_ticks = &Add_batches_ticks,
                    add_batches_values = &Add_batches_values,
                    add_batches_codes = &Add_batches_codes,
                    add_batches_flags = &Add_batches_flags,
                    add_batches_statuses = &Add_batches_statuses,
                };
                _fwd++;   // ak_decode_*
                int rc = Abi.ak_decode_ListMetricsResponse(_dctx, _drun, b, (nuint)len, &vt);
                if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}");
                int he = Abi.ak_dec_err(_dctx);
                if (he != 0) throw new InvalidOperationException($"host reported {he} through ak_fail");
            }
        }
        finally { h.Free(); }
        return target;
    }

    /// The pull family's record header. 24 bytes; the payload follows, padded to 8.
    [StructLayout(LayoutKind.Sequential)]
    private struct Rec { public uint Op, Slot; public long Token; public uint N, Bytes; }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;

    /// Parse, then replay. The parse makes ZERO reverse calls, which is the whole
    /// claim; the replay is managed code walking a byte buffer, so it makes none
    /// either. `ForwardCalls` counts two -- `ak_parse_*` and `ak_bdr_ptr` -- and
    /// `ReverseCalls` stays at zero, and that is the measurement.
    public ListMetricsResponse Pull(byte[] src, int len)
    {
        if (_dctx == IntPtr.Zero)
        {
            _dctx = Abi.ak_dec_ctx_new();
            _drun = (DecRun*)NativeMemory.Alloc((nuint)sizeof(DecRun));
        }
        var t = new ListMetricsResponse();
        fixed (byte* b = src)
        {
            _fwd++;
            int rc = Abi.ak_parse_ListMetricsResponse(_dctx, b, (nuint)len);
            if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}");
            byte* recs; nuint rlen;
            _fwd++;
            int pr = Abi.ak_bdr_ptr(_dctx, &recs, &rlen);
            if (pr != 0) throw new InvalidOperationException($"ak_bdr_ptr failed: {pr}");
            Replay(t, b, recs, (int)rlen);
        }
        return t;
    }

    private static void Replay(ListMetricsResponse t, byte* b, byte* p, int len)
    {
        int at = 0;
        while (at + sizeof(Rec) <= len)
        {
            ref var r = ref *(Rec*)(p + at);
            byte* body = p + at + sizeof(Rec);
            at += sizeof(Rec) + (int)r.Bytes;
            uint outer = r.Slot >> 16, inner = r.Slot & 0xFFFF;
            switch (r.Op)
            {
                case OP_APPLY:
                {
                    ref var d = ref *(ak_dfix_ListMetricsResponse*)body;
                    break;
                }
                case OP_NEW when outer == 1:
                    t.Batches.Add(new MetricsBatch());
                    break;
                case OP_APPLY_ELEM when outer == 1:
                {
                    var e = t.Batches[(int)r.Token];
                    ref var d = ref *(ak_dfix_MetricsBatch*)body;
                    e.Id = Str(b, d.id);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 1:
                {
                    var e = t.Batches[(int)r.Token];
                    var xs = (long*)body;
                    var lst = e.Ticks;
                    for (int i = 0; i < r.N; i++) lst.Add(xs[i]);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 2:
                {
                    var e = t.Batches[(int)r.Token];
                    var xs = (double*)body;
                    var lst = e.Values;
                    for (int i = 0; i < r.N; i++) lst.Add(xs[i]);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 3:
                {
                    var e = t.Batches[(int)r.Token];
                    var xs = (int*)body;
                    var lst = e.Codes;
                    for (int i = 0; i < r.N; i++) lst.Add(xs[i]);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 4:
                {
                    var e = t.Batches[(int)r.Token];
                    var xs = (byte*)body;
                    var lst = e.Flags;
                    for (int i = 0; i < r.N; i++) lst.Add(xs[i] != 0);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 5:
                {
                    var e = t.Batches[(int)r.Token];
                    var xs = (int*)body;
                    var lst = e.Statuses;
                    for (int i = 0; i < r.N; i++) lst.Add((TaskStatus)xs[i]);
                    break;
                }
                default: break;
            }
        }
    }

    /// Zero the host's own tally. The core's counters have their own reset.
    public void CallsReset() { _fwd = 0; _rev = 0; }
    /// What the PULL family trades the upcalls FOR: a record buffer in the decode
    /// context, proportional to the decoded payload. `ak_bdr_footprint` reports the
    /// high-water mark, so the trade can be read in both directions rather than only in
    /// time.
    public long PullFootprint() => _dctx == IntPtr.Zero ? 0 : (long)Abi.ak_bdr_footprint(_dctx);

    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dctx == IntPtr.Zero) return default; Abi.ak_dec_counters(_dctx, &c); return c; }
    public void DecCountersReset() { if (_dctx != IntPtr.Zero) Abi.ak_dec_counters_reset(_dctx); }

    public void Dispose()
    {
        if (_ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(_ctx); _ctx = IntPtr.Zero; }
        if (_dctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(_dctx); _dctx = IntPtr.Zero; }
        if (_staging != null) { NativeMemory.Free(_staging); _staging = null; }
        if (_run != null)
        {
            if (_run->S_batches != null) NativeMemory.AlignedFree(_run->S_batches);
            if (_run->I_batches_ticks != null) NativeMemory.AlignedFree(_run->I_batches_ticks);
            if (_run->O_batches_ticks != null) NativeMemory.Free(_run->O_batches_ticks);
            if (_run->C_batches_ticks != null) NativeMemory.Free(_run->C_batches_ticks);
            if (_run->I_batches_values != null) NativeMemory.AlignedFree(_run->I_batches_values);
            if (_run->O_batches_values != null) NativeMemory.Free(_run->O_batches_values);
            if (_run->C_batches_values != null) NativeMemory.Free(_run->C_batches_values);
            if (_run->I_batches_codes != null) NativeMemory.AlignedFree(_run->I_batches_codes);
            if (_run->O_batches_codes != null) NativeMemory.Free(_run->O_batches_codes);
            if (_run->C_batches_codes != null) NativeMemory.Free(_run->C_batches_codes);
            if (_run->I_batches_flags != null) NativeMemory.AlignedFree(_run->I_batches_flags);
            if (_run->O_batches_flags != null) NativeMemory.Free(_run->O_batches_flags);
            if (_run->C_batches_flags != null) NativeMemory.Free(_run->C_batches_flags);
            if (_run->I_batches_statuses != null) NativeMemory.AlignedFree(_run->I_batches_statuses);
            if (_run->O_batches_statuses != null) NativeMemory.Free(_run->O_batches_statuses);
            if (_run->C_batches_statuses != null) NativeMemory.Free(_run->C_batches_statuses);
            NativeMemory.Free(_run); _run = null;
        }
        if (_evt_batches != null) { NativeMemory.Free(_evt_batches); _evt_batches = null; }
        if (_drun != null) { NativeMemory.Free(_drun); _drun = null; }
    }
}
